-- Entrepreneurship course record. Safe to run more than once.
alter table public.courses add column if not exists video_url text;

insert into public.courses (slug, title, subject, credits, focus)
values ('entrepreneurship', 'Entrepreneurship and Business Stewardship', 'Electives', 1.0, $j$Entrepreneurship and Business Stewardship is a one credit elective that teaches students to see needs, plan wisely, serve customers honestly and manage resources as faithful stewards. Students study the entrepreneurial mindset, finding and testing business ideas, ethics and integrity, business structures and legal basics, customers and market research, competition and value propositions, pricing, marketing and branding, startup costs and funding, budgets, break even analysis, cash flow, records and taxes, honest selling, customer service, operations, suppliers and quality, technology and online safety, leadership and teamwork, hiring and wages, growth and risk, generosity and ministry, the business plan, the financial plan, pitching and launching. Each lesson connects to Scripture in the King James Version, and all Scripture quotations in the course are in the King James Version. The course includes six units, lesson checks, unit quizzes, assessments, discussions and a final business plan and exam. This course is education and practice only, not legal, tax or financial advice, and students must involve a parent, guardian or teacher before starting any real business, signing anything, borrowing money or sharing private information.$j$)
on conflict (slug) do nothing;
